"""Real core simulation, the previous ring and the bundled release artwork."""
import base64
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'evidence/editor/round4';OUT.mkdir(parents=True,exist_ok=True)
picture=base64.b64encode((ROOT/'docs/showcase/figures_design.png').read_bytes()).decode()
ready="""(async()=>{const start=performance.now();while(A.editor.lamp?.phase!=='ready'){if(A.editor.lamp?.phase==='error')throw Error(A.editor.lamp.error);if(performance.now()-start>90000)throw Error('Core preview timeout');await new Promise(r=>setTimeout(r,100));}await new Promise(r=>setTimeout(r,150));return {phase:A.editor.lamp.phase,width:A.editor.lamp.image.width,requests:renderRequests};})()"""
proof="""(()=>{const e=A.editor,image=e.lamp.image,c=document.createElement('canvas');c.width=c.height=image.width;const g=c.getContext('2d');g.drawImage(image,0,0);const a=g.getImageData(0,0,c.width,c.height).data;let chroma=0;for(let j=0;j<c.height;j++)for(let i=0;i<c.width;i++){const r=Math.hypot((i+.5)*120/c.width-60,60-(j+.5)*120/c.height);if(r<=48||r>=57)continue;const at=(j*c.width+i)*4,v=[a[at],a[at+1],a[at+2]];chroma=Math.max(chroma,Math.max(...v)-Math.min(...v));}if(chroma<15)throw Error('Missing radial colour in the unpatterned area');if(!renderPhases.some(p=>p.phase==='refining'&&p.width===200))throw Error('No quick preview');if(originalDocument!==JSON.stringify(e.document()))throw Error('Render changed the document');return {passed:true,phase:e.lamp.phase,size:image.width,radialChroma:chroma,phases:renderPhases,requests:renderRequests,pose:(()=>{const s=A.state(),cam=s.scene.cam;return {camera:[cam[0],s.lookY,cam[2]],flash:[cam[0]-43.66,s.lookY+19.79,cam[2]]};})()};})()"""
plan=[]
for theme,lang in [('light','zh'),('dark','zh'),('light','en'),('dark','en')]:
    prefix=f'{theme}-{lang}'
    setup="""(async()=>{globalThis.A=(await import('./design.js')).editorActions();globalThis.renderRequests=[];globalThis.renderPhases=[];const {LampPreview}=await import('./design/editor-lamp.mjs');const request=async(url,options)=>{const body=JSON.parse(options.body),log={size:body.size,quality:body.quality,start:performance.now()};renderRequests.push(log);const r=await fetch(url,options);log.status=r.status;log.cache=r.headers.get('X-Editor-Cache');if(r.ok){const bytes=await r.clone().arrayBuffer();log.png_sha256=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');}log.end=performance.now();return r;};A.editor.lamp?.pause();A.editor.lamp=new LampPreview({request,onChange:()=>{renderPhases.push({phase:A.editor.lamp.phase,width:A.editor.lamp.image?.width??0});A.editor.h.status?.();A.editor.h.draw();}});const e=A.editor;e.material='observation_0141';e.h.tool('ring');e.select({tool:'ring',inner:32,outer:46});e.options.fillKind='material';e.options.target='mask';e.fill();A.state().activeMask=null;e.h.changed();e.panels();globalThis.originalDocument=JSON.stringify(e.document());return {material:e.material,ring:[32,46]};})()"""
    steps=[dict(eval=f"localStorage.setItem('dp-theme','{theme}');localStorage.setItem('dp-lang','{lang}');location.reload()"),dict(wait=1400),dict(eval="document.querySelector('#lobby-new').click()"),dict(wait=350),dict(eval="document.querySelector('#next').click()"),dict(wait=1600),dict(eval=setup,print=True),dict(eval="document.querySelector('[data-v=lamp]').click()"),dict(wait=120),dict(shot=prefix+'-ring-progress'),dict(eval=ready,print=True),dict(shot=prefix+'-ring-lamp'),dict(eval=proof,print=True,save=prefix+'-ring-checks.json'),dict(eval='A.editor.document()',save=prefix+'-ring-work.json')]
    steps += [dict(eval="(()=>{const n=renderRequests.length;document.querySelector('[data-v=proj]').click();document.querySelector('[data-v=lamp]').click();A.editor.h.draw();globalThis.cachedRequestCount=n;})()"),dict(wait=300),dict(eval="if(renderRequests.length!==cachedRequestCount)throw Error('View cache missed')")]
    steps += [dict(eval="document.querySelector('[data-v=proj]').click()"),dict(eval=f"""(async()=>{{const s=A.state();s.layers=[];s.selections=[];s.assignments=[];s.activeMask=null;const bytes=Uint8Array.from(atob('{picture}'),c=>c.charCodeAt(0));await A.importFiles([new File([bytes],'figures_design.png',{{type:'image/png'}})]);const l=s.layers[0];Object.assign(l,{{width:116,x:0,y:0,rot:36}});A.editor.h.tool('pan');A.editor.h.changed();A.editor.h.rebuild();globalThis.originalDocument=JSON.stringify(A.editor.document());renderRequests.length=0;renderPhases.length=0;}})()"""),dict(eval="document.querySelector('[data-v=lamp]').click()"),dict(eval=ready,print=True),dict(shot=prefix+'-picture-lamp'),dict(eval=proof,print=True,save=prefix+'-picture-checks.json'),dict(eval='A.editor.document()',save=prefix+'-picture-work.json')]
    plan.append(dict(url='http://127.0.0.1:8796/home/index.html',theme=theme,steps=steps))
(OUT/'capture-plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2),encoding='utf8')
